def start_feature_clarification(featureName, initialDescription=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0267000" if __import__("os").path.isdir("./environment_mix/0267000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request log + quota/rate limiting (best-effort; schema not provided)
    def _log(status, credential_used=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "start_feature_clarification",
                "timestamp": now,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "credential": credential_used,
            }
            if meta is not None:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Very small generic rate-limit to make dynamics observable if logs exist
    def _enforce_limits():
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            # 120 req/min global (no explicit auth context in this service)
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-2000:]:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.replace(tzinfo=None) >= cutoff:
                    cnt += 1
            if cnt >= 120:
                return _err("RATE_LIMIT", "Too many requests. Please slow down.")
        except Exception:
            return None
        return None

    lim = _enforce_limits()
    if lim:
        _log("error", meta=lim["error"])
        return lim

    # Validate inputs
    if not isinstance(featureName, str):
        e = _err("VALIDATION_ERROR", "featureName must be a string.")
        _log("error", meta=e["error"])
        return e
    if len(featureName) < 2 or len(featureName) > 100:
        e = _err("VALIDATION_ERROR", "featureName length must be between 2 and 100.")
        _log("error", meta=e["error"])
        return e
    if initialDescription is None:
        initialDescription = ""
    if not isinstance(initialDescription, str):
        e = _err("VALIDATION_ERROR", "initialDescription must be a string.")
        _log("error", meta=e["error"])
        return e

    features = _load("features.json")
    if not isinstance(features, list):
        features = []

    # Enforce uniqueness of feature_name (global, single-tenant)
    for f in features:
        if isinstance(f, dict) and f.get("feature_name") == featureName:
            e = _err("CONFLICT", "A feature with this featureName already exists.", field="featureName")
            _log("error", meta=e["error"])
            return e

    # Quota: max number of non-archived features (simple service-wide quota)
    try:
        active_cnt = sum(1 for f in features if isinstance(f, dict) and f.get("status") != "archived")
        if active_cnt >= 200:
            e = _err("QUOTA_EXCEEDED", "Maximum number of active features reached.")
            _log("error", meta=e["error"])
            return e
    except Exception:
        pass

    feature_id = "feat_" + uuid.uuid4().hex
    row = {
        "id": feature_id,
        "feature_name": featureName,
        "initial_description": initialDescription,
        "status": "clarifying",
        "active_phase_id": None,
        "clarification_open_count": 0,
        "clarification_answered_count": 0,
        "prd_version": 0,
        "created_at": now,
        "updated_at": now,
    }
    features.append(row)
    try:
        _save("features.json", features)
    except Exception as ex:
        e = _err("CONFLICT", "Failed to persist feature.", detail=str(ex))
        _log("error", meta=e["error"])
        return e

    resp = {"feature": row}
    _log("ok")
    return resp

def generate_prd(featureId, **_extra):
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0267000" if __import__("os").path.isdir("./environment_mix/0267000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_used=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "generate_prd",
                "timestamp": now,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "credential": credential_used,
            }
            if meta is not None:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _enforce_limits():
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-2000:]:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.replace(tzinfo=None) >= cutoff:
                    cnt += 1
            if cnt >= 120:
                return _err("RATE_LIMIT", "Too many requests. Please slow down.")
        except Exception:
            return None
        return None

    lim = _enforce_limits()
    if lim:
        _log("error", meta=lim["error"])
        return lim

    if not isinstance(featureId, str) or len(featureId) < 1:
        e = _err("VALIDATION_ERROR", "featureId must be a non-empty string.")
        _log("error", meta=e["error"])
        return e

    features = _load("features.json")
    if not isinstance(features, list):
        features = []
    documents = _load("documents.json")
    if not isinstance(documents, list):
        documents = []

    feat = None
    feat_idx = None
    for i, f in enumerate(features):
        if isinstance(f, dict) and f.get("id") == featureId:
            feat = f
            feat_idx = i
            break
    if not feat:
        e = _err("NOT_FOUND", "Feature not found.", featureId=featureId)
        _log("error", meta=e["error"])
        return e

    if feat.get("status") == "archived":
        e = _err("CONFLICT", "Cannot generate PRD for an archived feature.", status="archived")
        _log("error", meta=e["error"])
        return e

    # Increment PRD version
    try:
        cur_ver = int(feat.get("prd_version", 0))
        if cur_ver < 0:
            raise ValueError("prd_version < 0")
    except Exception:
        e = _err("CONFLICT", "Corrupt feature prd_version.")
        _log("error", meta=e["error"])
        return e

    new_ver = cur_ver + 1

    # Determine file_path (computed); generation is assumed to succeed offline
    safe_name = (feat.get("feature_name") or "feature").strip()
    if not isinstance(safe_name, str) or safe_name == "":
        safe_name = "feature"
    slug = "".join(ch.lower() if ch.isalnum() else "-" for ch in safe_name).strip("-")
    if not slug:
        slug = "feature"
    file_path = f"/vibe-coder/features/{featureId}/prd/v{new_ver}-{slug}.md"

    # Enforce "at most one non-archived latest" per (feature_id, document_type) via app logic:
    # archive all non-archived existing PRDs (draft/generated/saved)
    for d in documents:
        if isinstance(d, dict) and d.get("feature_id") == featureId and d.get("document_type") == "prd" and d.get("status") != "archived":
            # lifecycle allows draft/generated/saved -> archived
            d["status"] = "archived"
            d["updated_at"] = now

    doc_id = "doc_" + uuid.uuid4().hex
    content_sig = f"{featureId}|prd|v{new_ver}|{file_path}".encode("utf-8")
    sha = hashlib.sha256(content_sig).hexdigest()
    doc = {
        "id": doc_id,
        "feature_id": featureId,
        "document_type": "prd",
        "status": "generated",
        "file_path": file_path,
        "content_sha256": sha,
        "version": new_ver,
        "source": "generated",
        "created_at": now,
        "updated_at": now,
    }
    documents.append(doc)

    # Feature status: set to at least prd_generated (no downgrade)
    order = ["clarifying", "prd_generated", "planning", "in_execution", "completed", "archived"]
    cur_status = feat.get("status")
    if cur_status not in order:
        e = _err("CONFLICT", "Invalid feature status in store.", status=cur_status)
        _log("error", meta=e["error"])
        return e
    if order.index(cur_status) < order.index("prd_generated"):
        # transition clarifying -> prd_generated allowed
        feat["status"] = "prd_generated"
    # Always bump version after success
    feat["prd_version"] = new_ver
    feat["updated_at"] = now
    features[feat_idx] = feat

    try:
        _save("documents.json", documents)
        _save("features.json", features)
    except Exception as ex:
        e = _err("CONFLICT", "Failed to persist PRD generation result.", detail=str(ex))
        _log("error", meta=e["error"])
        return e

    resp = {"feature": feat, "document": doc}
    _log("ok")
    return resp

def create_phase(featureId, name, description, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0267000" if __import__("os").path.isdir("./environment_mix/0267000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_used=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "create_phase",
                "timestamp": now,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "credential": credential_used,
            }
            if meta is not None:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _enforce_limits():
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return None
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-2000:]:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.replace(tzinfo=None) >= cutoff:
                    cnt += 1
            if cnt >= 120:
                return _err("RATE_LIMIT", "Too many requests. Please slow down.")
        except Exception:
            return None
        return None

    lim = _enforce_limits()
    if lim:
        _log("error", meta=lim["error"])
        return lim

    if not isinstance(featureId, str) or len(featureId) < 1:
        e = _err("VALIDATION_ERROR", "featureId must be a non-empty string.")
        _log("error", meta=e["error"])
        return e
    if not isinstance(name, str) or len(name) < 1:
        e = _err("VALIDATION_ERROR", "name must be a non-empty string.")
        _log("error", meta=e["error"])
        return e
    if not isinstance(description, str) or len(description) < 1:
        e = _err("VALIDATION_ERROR", "description must be a non-empty string.")
        _log("error", meta=e["error"])
        return e

    features = _load("features.json")
    if not isinstance(features, list):
        features = []
    phases = _load("phases.json")
    if not isinstance(phases, list):
        phases = []

    feat = None
    feat_idx = None
    for i, f in enumerate(features):
        if isinstance(f, dict) and f.get("id") == featureId:
            feat = f
            feat_idx = i
            break
    if not feat:
        e = _err("NOT_FOUND", "Feature not found.", featureId=featureId)
        _log("error", meta=e["error"])
        return e

    if feat.get("status") == "archived":
        e = _err("CONFLICT", "Cannot create phases for an archived feature.", status="archived")
        _log("error", meta=e["error"])
        return e

    # Enforce unique(feature_id, name)
    for p in phases:
        if isinstance(p, dict) and p.get("feature_id") == featureId and p.get("name") == name:
            e = _err("CONFLICT", "A phase with this name already exists for the feature.", field="name")
            _log("error", meta=e["error"])
            return e

    # Assign sequence_index = max + 1 within feature
    max_idx = -1
    for p in phases:
        if isinstance(p, dict) and p.get("feature_id") == featureId:
            try:
                si = int(p.get("sequence_index", -1))
            except Exception:
                continue
            if si > max_idx:
                max_idx = si
    seq = max_idx + 1
    if seq < 0:
        seq = 0

    # Enforce unique(feature_id, sequence_index)
    for p in phases:
        if isinstance(p, dict) and p.get("feature_id") == featureId and p.get("sequence_index") == seq:
            e = _err("CONFLICT", "Phase sequence_index conflict.", sequence_index=seq)
            _log("error", meta=e["error"])
            return e

    phase_id = "ph_" + uuid.uuid4().hex
    phase = {
        "id": phase_id,
        "feature_id": featureId,
        "name": name,
        "description": description,
        "sequence_index": seq,
        "status": "pending",
        "started_at": None,
        "completed_at": None,
        "reviewed_at": None,
        "created_at": now,
        "updated_at": now,
    }
    phases.append(phase)

    # If no active_phase_id, set to new one
    if feat.get("active_phase_id") in (None, ""):
        feat["active_phase_id"] = phase_id

    # Promote features.status to at least 'planning' if earlier
    order = ["clarifying", "prd_generated", "planning", "in_execution", "completed", "archived"]
    cur_status = feat.get("status")
    if cur_status not in order:
        e = _err("CONFLICT", "Invalid feature status in store.", status=cur_status)
        _log("error", meta=e["error"])
        return e
    if order.index(cur_status) < order.index("planning"):
        # only legal transitions: clarifying->prd_generated->planning; allow direct promotion by stepping
        # if currently clarifying, require PRD already? business rules allow promotion; but keep lifecycle legality:
        if cur_status == "clarifying":
            # can't jump to planning directly per transitions; promote to prd_generated first then planning is still a jump.
            # Treat as CONFLICT: needs generate_prd first.
            e = _err("CONFLICT", "Cannot enter planning before PRD is generated.", status=cur_status)
            _log("error", meta=e["error"])
            return e
        if cur_status == "prd_generated":
            feat["status"] = "planning"

    feat["updated_at"] = now
    features[feat_idx] = feat

    try:
        _save("phases.json", phases)
        _save("features.json", features)
    except Exception as ex:
        e = _err("CONFLICT", "Failed to persist phase.", detail=str(ex))
        _log("error", meta=e["error"])
        return e

    resp = {"phase": phase, "feature": feat}
    _log("ok")
    return resp

def add_task(featureId, phaseId, description, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0267000" if __import__("os").path.isdir("./environment_mix/0267000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add_task"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(error_code=None, http_status=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": "error" if error_code else "ok",
            "error_code": error_code,
            "http_status": http_status if http_status is not None else (400 if error_code else 200),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if not isinstance(featureId, str) or not featureId.strip():
        e = _err("VALIDATION_ERROR", "featureId must be a non-empty string")
        _log("VALIDATION_ERROR", 400, e["error"])
        return e
    if not isinstance(phaseId, str) or not phaseId.strip():
        e = _err("VALIDATION_ERROR", "phaseId must be a non-empty string")
        _log("VALIDATION_ERROR", 400, e["error"])
        return e
    if not isinstance(description, str) or len(description) < 1:
        e = _err("VALIDATION_ERROR", "description must be a non-empty string")
        _log("VALIDATION_ERROR", 400, e["error"])
        return e

    features = _load("features.json")
    phases = _load("phases.json")
    tasks = _load("tasks.json")
    if not isinstance(features, list):
        features = []
    if not isinstance(phases, list):
        phases = []
    if not isinstance(tasks, list):
        tasks = []

    feat = next((f for f in features if isinstance(f, dict) and f.get("id") == featureId), None)
    if not feat:
        e = _err("NOT_FOUND", "featureId not found", featureId=featureId)
        _log("NOT_FOUND", 404, e["error"])
        return e

    # Find phase by id; tolerate common client error where featureId was passed as phaseId by falling back to active_phase_id.
    phase = next((p for p in phases if isinstance(p, dict) and p.get("id") == phaseId), None)
    used_phase_id = phaseId
    if phase is None:
        active_id = feat.get("active_phase_id")
        if isinstance(active_id, str) and active_id:
            phase = next((p for p in phases if isinstance(p, dict) and p.get("id") == active_id), None)
            if phase is not None:
                used_phase_id = active_id

    if phase is None:
        e = _err("NOT_FOUND", "phaseId not found", featureId=featureId, phaseId=phaseId)
        _log("NOT_FOUND", 404, e["error"])
        return e

    if phase.get("feature_id") != featureId:
        e = _err("NOT_FOUND", "phaseId not found for featureId", featureId=featureId, phaseId=phaseId)
        _log("NOT_FOUND", 404, e["error"])
        return e

    # Determine next sequence_index within phase
    max_idx = -1
    for t in tasks:
        if isinstance(t, dict) and t.get("phase_id") == used_phase_id:
            si = t.get("sequence_index")
            if isinstance(si, int) and si > max_idx:
                max_idx = si
    next_idx = max_idx + 1

    # Generate id
    now = _now_iso()
    new_id = f"vbc_task_{int(time.time()*1000)}_{len(tasks)+1}"

    task = {
        "id": new_id,
        "feature_id": featureId,
        "phase_id": used_phase_id,
        "description": description,
        "sequence_index": next_idx,
        "status": "pending",
        "completed": False,
        "completed_at": None,
        "created_at": now,
        "updated_at": now
    }

    tasks.append(task)
    _save("tasks.json", tasks)

    _log(None, 200, {"featureId": featureId, "phaseId": used_phase_id, "taskId": new_id})
    return {"task": task, "featureId": featureId, "phaseId": used_phase_id}

def get_next_phase_action(featureId, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0267000" if __import__("os").path.isdir("./environment_mix/0267000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    endpoint = "get_next_phase_action"
    def _log(status_code, error_code=None):
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": "error" if error_code else "ok",
            "error_code": error_code,
            "http_status": status_code
        })
        _save("request_logs.json", logs)

    if not isinstance(featureId, str) or not featureId.strip():
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "featureId must be a non-empty string")

    features = _load("features.json")
    phases = _load("phases.json")
    tasks = _load("tasks.json")
    if not isinstance(features, list):
        features = []
    if not isinstance(phases, list):
        phases = []
    if not isinstance(tasks, list):
        tasks = []

    feat = next((r for r in features if isinstance(r, dict) and r.get("id") == featureId), None)
    if not feat:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "featureId not found", featureId=featureId)

    feat_phases = [p for p in phases if isinstance(p, dict) and p.get("feature_id") == featureId]
    feat_phases.sort(key=lambda p: (p.get("sequence_index", 0), p.get("created_at", "")))

    if not feat_phases:
        _log(409, "CONFLICT")
        return _err("CONFLICT", "No phases exist for feature; cannot determine next action", featureId=featureId)

    phases_by_id = {p.get("id"): p for p in feat_phases if isinstance(p, dict) and p.get("id")}

    active_id = feat.get("active_phase_id")
    active_phase = phases_by_id.get(active_id) if active_id else None

    def _phase_tasks(phase_id):
        pt = [t for t in tasks if isinstance(t, dict) and t.get("phase_id") == phase_id and t.get("feature_id") == featureId]
        pt.sort(key=lambda t: (t.get("sequence_index", 0), t.get("created_at", "")))
        return pt

    # Choose phase: prefer active_phase_id if exists and not reviewed; otherwise pick first not-reviewed by sequence_index
    phase = None
    if active_phase and active_phase.get("status") != "reviewed":
        phase = active_phase
    else:
        for p in feat_phases:
            if p.get("status") != "reviewed":
                phase = p
                break

    # If active phase is reviewed, advance to next by sequence_index and persist
    if active_phase and active_phase.get("status") == "reviewed":
        # find next by sequence_index
        next_phase = None
        try:
            a_seq = int(active_phase.get("sequence_index", -1))
        except Exception:
            a_seq = -1
        for p in feat_phases:
            try:
                if int(p.get("sequence_index", -1)) > a_seq:
                    next_phase = p
                    break
            except Exception:
                continue
        if next_phase:
            feat["active_phase_id"] = next_phase.get("id")
            feat["updated_at"] = now
            _save("features.json", features)
            phase = next_phase
        else:
            # no next phase; if all reviewed, no action
            if all(p.get("status") == "reviewed" for p in feat_phases):
                _log(409, "CONFLICT")
                return _err("CONFLICT", "All phases reviewed; no next action", featureId=featureId)
            # otherwise, choose first not-reviewed already handled; but none found means conflict
            _log(409, "CONFLICT")
            return _err("CONFLICT", "No next phase available", featureId=featureId)

    if not phase:
        _log(409, "CONFLICT")
        return _err("CONFLICT", "No actionable phase found", featureId=featureId)

    ptasks = _phase_tasks(phase.get("id"))
    pending = next((t for t in ptasks if t.get("status") == "pending" and t.get("completed") is False), None)
    if pending:
        _log(200, None)
        return {
            "action": {
                "type": "complete_task",
                "feature_id": featureId,
                "phase_id": phase.get("id"),
                "task_id": pending.get("id"),
                "description": pending.get("description"),
                "reason": "First pending task by sequence_index in the selected phase"
            },
            "phase": phase,
            "task": pending
        }

    # No pending tasks in this phase; suggest phase status transitions based on current phase status
    pstatus = phase.get("status")
    if pstatus == "in_progress":
        _log(200, None)
        return {
            "action": {
                "type": "update_phase_status",
                "feature_id": featureId,
                "phase_id": phase.get("id"),
                "to_status": "completed",
                "reason": "No pending tasks remain and phase is in_progress"
            },
            "phase": phase
        }
    if pstatus == "completed":
        _log(200, None)
        return {
            "action": {
                "type": "update_phase_status",
                "feature_id": featureId,
                "phase_id": phase.get("id"),
                "to_status": "reviewed",
                "reason": "Phase is completed; next step is reviewed"
            },
            "phase": phase
        }
    if pstatus == "pending":
        _log(200, None)
        return {
            "action": {
                "type": "update_phase_status",
                "feature_id": featureId,
                "phase_id": phase.get("id"),
                "to_status": "in_progress",
                "reason": "Phase is pending; next step is to start it"
            },
            "phase": phase
        }

    # If reviewed, we should have advanced earlier; fall back to conflict
    _log(409, "CONFLICT")
    return _err("CONFLICT", "No next action could be determined", featureId=featureId, phaseId=phase.get("id"), phase_status=pstatus)

def get_document_path(featureId, documentType, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0267000" if __import__("os").path.isdir("./environment_mix/0267000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_document_path"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(error_code=None, http_status=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": "error" if error_code else "ok",
            "error_code": error_code,
            "http_status": http_status if http_status is not None else (400 if error_code else 200),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(featureId, str) or len(featureId) < 1:
        e = _err("VALIDATION_ERROR", "featureId must be a non-empty string")
        _log("VALIDATION_ERROR", 400, e["error"])
        return e
    if not isinstance(documentType, str) or len(documentType) < 1:
        e = _err("VALIDATION_ERROR", "documentType must be a non-empty string")
        _log("VALIDATION_ERROR", 400, e["error"])
        return e

    features = _load("features.json")
    if not isinstance(features, list):
        features = []
    if not any(isinstance(f, dict) and f.get("id") == featureId for f in features):
        e = _err("NOT_FOUND", "featureId not found", featureId=featureId)
        _log("NOT_FOUND", 404, e["error"])
        return e

    documents = _load("documents.json")
    if not isinstance(documents, list):
        documents = []

    # Latest non-archived by highest version
    candidates = []
    for d in documents:
        if not isinstance(d, dict):
            continue
        if d.get("feature_id") != featureId:
            continue
        if d.get("document_type") != documentType:
            continue
        if d.get("status") == "archived":
            continue
        v = d.get("version")
        if not isinstance(v, int):
            continue
        candidates.append(d)

    candidates.sort(key=lambda d: d.get("version", 0), reverse=True)
    latest = candidates[0] if candidates else None

    # Per business rules: if none exists OR file_path is null -> return empty/not-found result, not fabricated.
    if not latest or not latest.get("file_path"):
        # Read tools: "filters match nothing returns an empty result set with the normal envelope"
        resp = {
            "featureId": featureId,
            "documentType": documentType,
            "filePath": None,
            "found": False
        }
        _log(None, 200, {"found": False})
        return resp

    resp = {
        "featureId": featureId,
        "documentType": documentType,
        "filePath": latest.get("file_path"),
        "found": True,
        "version": latest.get("version"),
        "documentId": latest.get("id")
    }
    _log(None, 200, {"found": True, "documentId": latest.get("id"), "version": latest.get("version")})
    return resp

def save_document(featureId, documentType, filePath=None, **_extra):
    import json, os, datetime, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0267000" if __import__("os").path.isdir("./environment_mix/0267000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    endpoint = "save_document"

    def _log(status, code=None, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        t1 = datetime.datetime.utcnow()
        row = {
            "id": f"req_{int(t1.timestamp()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "latency_ms": int((t1 - t0).total_seconds() * 1000),
            "timestamp": t1.replace(microsecond=0).isoformat() + "Z",
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(featureId, str) or len(featureId) < 1:
        _log("error", "VALIDATION_ERROR", "featureId must be a non-empty string")
        return _err("VALIDATION_ERROR", "featureId must be a non-empty string")
    if not isinstance(documentType, str) or len(documentType) < 1:
        _log("error", "VALIDATION_ERROR", "documentType must be a non-empty string")
        return _err("VALIDATION_ERROR", "documentType must be a non-empty string")
    if filePath is not None:
        if not isinstance(filePath, str):
            _log("error", "VALIDATION_ERROR", "filePath must be a string when provided")
            return _err("VALIDATION_ERROR", "filePath must be a string when provided")
        if len(filePath) < 1:
            _log("error", "VALIDATION_ERROR", "filePath must be non-empty when provided")
            return _err("VALIDATION_ERROR", "filePath must be non-empty when provided")

    features = _load("features.json")
    if not any(isinstance(f, dict) and f.get("id") == featureId for f in features):
        _log("error", "NOT_FOUND", "Feature not found", {"featureId": featureId})
        return _err("NOT_FOUND", "Feature not found", featureId=featureId)

    documents = _load("documents.json")
    if not isinstance(documents, list):
        documents = []

    # Find latest non-archived for this doc type
    existing = [
        d for d in documents
        if isinstance(d, dict)
        and d.get("feature_id") == featureId
        and d.get("document_type") == documentType
        and d.get("status") != "archived"
        and isinstance(d.get("version"), int)
    ]
    existing.sort(key=lambda d: d.get("version", 0), reverse=True)
    latest = existing[0] if existing else None

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # PATCH semantics: if filePath omitted, keep file_path unchanged
    new_file_path = filePath if filePath is not None else (latest.get("file_path") if latest else None)

    # If filePath omitted and nothing exists yet, we can still create a record (file_path may be null)
    # Only bump version when "content changed" — we only have filePath, so treat change in file_path as change.
    def _hash_fp(fp):
        if fp is None:
            return None
        return hashlib.sha256(fp.encode("utf-8")).hexdigest()

    new_hash = _hash_fp(new_file_path)
    old_hash = latest.get("content_sha256") if latest else None
    if latest and filePath is None:
        # no explicit new path; if no effective change, idempotent return
        if (latest.get("file_path") == new_file_path) and (old_hash == new_hash):
            _log("ok", meta={"featureId": featureId, "documentType": documentType, "idempotent": True, "version": latest.get("version")})
            return {
                "featureId": featureId,
                "documentType": documentType,
                "filePath": latest.get("file_path"),
                "document": latest,
            }

    # Determine next version
    max_ver = 0
    for d in documents:
        if isinstance(d, dict) and d.get("feature_id") == featureId and d.get("document_type") == documentType and isinstance(d.get("version"), int):
            if d["version"] > max_ver:
                max_ver = d["version"]
    next_ver = max_ver + 1
    if next_ver < 1:
        _log("error", "VALIDATION_ERROR", "Computed document version is invalid")
        return _err("VALIDATION_ERROR", "Computed document version is invalid")

    # Enforce source/status consistency rules for user_saved
    status = "saved"
    source = "user_saved"
    if status not in ("saved", "archived"):
        _log("error", "VALIDATION_ERROR", "Invalid status for user-saved document")
        return _err("VALIDATION_ERROR", "Invalid status for user-saved document")

    # Enforce file_path constraint: for saved status, file_path length >= 1
    # Business rule allows omitted filePath while still storing/updating; but if it results in null/empty, reject.
    if status in ("generated", "saved"):
        if not isinstance(new_file_path, str) or len(new_file_path) < 1:
            _log("error", "VALIDATION_ERROR", "filePath is required to save a document path for saved documents")
            return _err("VALIDATION_ERROR", "filePath is required to save a document path for saved documents", featureId=featureId, documentType=documentType)

    # Application logic: "at most one non-archived 'latest' version per (feature_id, document_type)"
    # This is naturally satisfied by keeping older ones non-archived; interpret as: only the highest version is "latest".
    # We don't need to archive older versions, but to keep a single "current" mapping, archive prior non-archived rows.
    # (This also prevents ambiguity for get_document_path.)
    changed = False
    for d in documents:
        if isinstance(d, dict) and d.get("feature_id") == featureId and d.get("document_type") == documentType and d.get("status") != "archived":
            d["status"] = "archived"
            d["updated_at"] = now
            changed = True

    new_doc = {
        "id": f"doc_{featureId}_{documentType}_{next_ver}",
        "feature_id": featureId,
        "document_type": documentType,
        "status": "saved",
        "file_path": new_file_path,
        "content_sha256": new_hash,
        "version": next_ver,
        "source": source,
        "created_at": now,
        "updated_at": now,
    }

    # Uniqueness: (feature_id, document_type, version)
    if any(isinstance(d, dict) and d.get("feature_id") == featureId and d.get("document_type") == documentType and d.get("version") == next_ver for d in documents):
        _log("error", "CONFLICT", "Document version already exists", {"featureId": featureId, "documentType": documentType, "version": next_ver})
        return _err("CONFLICT", "Document version already exists", featureId=featureId, documentType=documentType, version=next_ver)

    documents.append(new_doc)
    _save("documents.json", documents)

    _log("ok", meta={"featureId": featureId, "documentType": documentType, "version": next_ver, "archived_prev": changed})
    return {
        "featureId": featureId,
        "documentType": documentType,
        "filePath": new_doc.get("file_path"),
        "document": new_doc,
    }

def list_features(status=None, query=None, createdAfter=None, createdBefore=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0267000" if __import__("os").path.isdir("./environment_mix/0267000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    endpoint = "list_features"

    def _log(status_s, code=None, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        t1 = datetime.datetime.utcnow()
        row = {
            "id": f"req_{int(t1.timestamp()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_s,
            "error_code": code,
            "error_message": message,
            "latency_ms": int((t1 - t0).total_seconds() * 1000),
            "timestamp": t1.replace(microsecond=0).isoformat() + "Z",
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    allowed_status = {"clarifying", "prd_generated", "planning", "in_execution", "completed", "archived"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("error", "VALIDATION_ERROR", "Invalid status filter")
        return _err("VALIDATION_ERROR", "Invalid status filter", allowed=sorted(list(allowed_status)))
    if query is not None:
        if not isinstance(query, str) or len(query) < 1:
            _log("error", "VALIDATION_ERROR", "query must be a non-empty string when provided")
            return _err("VALIDATION_ERROR", "query must be a non-empty string when provided")
    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", "VALIDATION_ERROR", "limit must be an integer between 1 and 100")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if sort is None:
        sort = "updated_at"
    if sort not in ("created_at", "updated_at"):
        _log("error", "VALIDATION_ERROR", "sort must be 'created_at' or 'updated_at'")
        return _err("VALIDATION_ERROR", "sort must be 'created_at' or 'updated_at'")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        _log("error", "VALIDATION_ERROR", "order must be 'asc' or 'desc'")
        return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'")

    def _parse_dt(s, fieldname):
        if s is None:
            return None, None
        if not isinstance(s, str) or len(s) < 1:
            return None, _err("VALIDATION_ERROR", f"{fieldname} must be an ISO-8601 date-time string")
        ss = s[:-1] if s.endswith("Z") else s
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{fieldname} must be an ISO-8601 date-time string")
        return dt, None

    created_after_dt, e = _parse_dt(createdAfter, "createdAfter")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    created_before_dt, e = _parse_dt(createdBefore, "createdBefore")
    if e:
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Decode cursor: base64 of JSON {"i": int}
    start_index = 0
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) < 1:
            _log("error", "VALIDATION_ERROR", "cursor must be a non-empty string when provided")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"=" * (-len(cursor) % 4)).decode("utf-8")
            obj = json.loads(raw)
        except Exception:
            _log("error", "NOT_FOUND", "Invalid cursor")
            return _err("NOT_FOUND", "Invalid cursor")
        if not isinstance(obj, dict) or not isinstance(obj.get("i"), int) or obj["i"] < 0:
            _log("error", "NOT_FOUND", "Invalid cursor")
            return _err("NOT_FOUND", "Invalid cursor")
        start_index = obj["i"]

    features = _load("features.json")
    if not isinstance(features, list):
        features = []

    def _dt_or_none(s):
        if not isinstance(s, str):
            return None
        ss = s[:-1] if s.endswith("Z") else s
        try:
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    q = query.lower() if isinstance(query, str) else None

    filtered = []
    for f in features:
        if not isinstance(f, dict):
            continue
        if status is not None and f.get("status") != status:
            continue
        if q is not None:
            n = f.get("feature_name") or ""
            d = f.get("initial_description") or ""
            if q not in str(n).lower() and q not in str(d).lower():
                continue
        cdt = _dt_or_none(f.get("created_at"))
        if created_after_dt is not None:
            if cdt is None or cdt < created_after_dt:
                continue
        if created_before_dt is not None:
            if cdt is None or cdt >= created_before_dt:
                continue
        filtered.append(f)

    reverse = (order == "desc")
    def _sort_key(f):
        dt = _dt_or_none(f.get(sort))
        # push invalid/missing to the end deterministically
        return (0, dt, f.get("id")) if dt is not None else (1, datetime.datetime.min, f.get("id"))
    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    if start_index > total:
        _log("error", "NOT_FOUND", "Invalid cursor")
        return _err("NOT_FOUND", "Invalid cursor")

    page = filtered[start_index:start_index + limit]
    next_index = start_index + len(page)
    has_more = next_index < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"i": next_index}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log("ok", meta={"returned": len(page), "total": total, "has_more": has_more})
    return {
        "data": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "sort": {"field": sort, "order": order},
        "filters": {
            "status": status,
            "query": query,
            "createdAfter": createdAfter,
            "createdBefore": createdBefore,
        },
    }

