        return e

    allowed_statuses = ["clarifying", "prd_generated", "planning", "in_execution", "completed", "archived"]
    if not isinstance(status, str) or status not in allowed_statuses:
        e = _err("VALIDATION_ERROR", "status must be one of the allowed lifecycle values", allowed=allowed_statuses)
        _log("VALIDATION_ERROR", 400, e["error"])
        return e

    features = _load("features.json")
    if not isinstance(features, list):
        features = []

    feat_idx = None
    for i, f in enumerate(features):
        if isinstance(f, dict) and f.get("id") == featureId:
            feat_idx = i
            break
    if feat_idx is None:
        e = _err("NOT_FOUND", "featureId not found", featureId=featureId)
        _log("NOT_FOUND", 404, e["error"])
        return e

    feat = features[feat_idx]
    current = feat.get("status")
    if current not in allowed_statuses:
        e = _err("CONFLICT", "feature has invalid stored status", featureId=featureId, status=current)
        _log("CONFLICT", 409, e["error"])
        return e

    transitions = {
        "clarifying": ["prd_generated", "archived"],
        "prd_generated": ["planning", "archived"],
        "planning": ["in_execution", "archived"],
        "in_execution": ["completed", "archived"],
        "completed": ["archived"],
        "archived": [],
    }

    # Idempotent: allow setting to same status
    if status != current:
        allowed = transitions.get(current, [])
        if status not in allowed:
            e = _err(
                "INVALID_TRANSITION",
                "requested feature status transition is not allowed by lifecycle rules",
                rule="features.status transitions",
                from_status=current,
                to_status=status,
                allowed=allowed,
                featureId=featureId,
            )
            _log("INVALID_TRANSITION", 409, e["error"])
            return e

    now = _now_iso()
    feat["status"] = status
    feat["updated_at"] = now

    # If archiving: clear active_phase_id (application policy) only if it references this feature's phase; otherwise leave
    if status == "archived":
        active_pid = feat.get("active_phase_id")
        if active_pid:
            phases = _load("phases.json")
            if isinstance(phases, list):
                for p in phases:
                    if isinstance(p, dict) and p.get("id") == active_pid:
                        if p.get("feature_id") == featureId:
                            feat["active_phase_id"] = None
                        break

    features[feat_idx] = feat
    _save("features.json", features)

    resp = {"feature": feat}
    _log(None, 200, {"featureId": featureId, "status": status})
    return resp

def list_clarifications(featureId, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0267000" if __import__("os").path.isdir("./environment_mix/0267000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status_code, credential_used=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "credential": credential_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(featureId, str) or len(featureId) < 1:
        _log("list_clarifications", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "featureId must be a non-empty string.")
    allowed_status = ["open", "answered", "superseded"]
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("list_clarifications", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of the allowed values.", allowed=allowed_status)
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("list_clarifications", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and (not isinstance(cursor, str) or len(cursor) < 1):
        _log("list_clarifications", 400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    # Feature existence
    features = _load("features.json")
    if not isinstance(features, list):
        features = []
    if not any(isinstance(f, dict) and f.get("id") == featureId for f in features):
        _log("list_clarifications", 404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Feature not found.", featureId=featureId)

    # Cursor decode: base64url JSON {"after_id": "..."}; if invalid => VALIDATION_ERROR
    after_id = None
    if cursor is not None:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or ("after_id" not in obj):
                _log("list_clarifications", 400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            after_id = obj.get("after_id")
            if after_id is not None and not isinstance(after_id, str):
                _log("list_clarifications", 400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            _log("list_clarifications", 400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    clarifications = _load("clarifications.json")
    if not isinstance(clarifications, list):
        clarifications = []

    rows = [c for c in clarifications if isinstance(c, dict) and c.get("feature_id") == featureId]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]

    # Sort by asked_at then created_at then id, oldest first
    def _key(c):
        a = _parse_ts(c.get("asked_at")) or _parse_ts(c.get("created_at")) or datetime.datetime(1970, 1, 1)
        b = _parse_ts(c.get("created_at")) or a
        cid = c.get("id") or ""
        return (a, b, cid)

    rows.sort(key=_key)

    # Apply cursor
    start = 0
    if after_id is not None:
        pos = None
        for i, c in enumerate(rows):
            if c.get("id") == after_id:
                pos = i
                break
        if pos is not None:
            start = pos + 1
        else:
            # Cursor points to a row not in this filtered set: treat as invalid
            _log("list_clarifications", 400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cursor does not match the current query result set.")
    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = None
    if has_more and page:
        payload = json.dumps({"after_id": page[-1].get("id")}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log("list_clarifications", 200)
    return {
        "clarifications": page,
        "pagination": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

